import os
import json

# Assuming workspace path is current directory or specified
workspace_path = os.getcwd()
policy_files = []

# List files in workspace to find policy documents
for file in os.listdir(workspace_path):
    if file.endswith('.json') or file.endswith('.txt') or file.endswith('.md'):
        policy_files.append(file)

print("Found policy files:", policy_files)

# Read each policy file
policy_contents = {}
for file in policy_files:
    try:
        with open(os.path.join(workspace_path, file), 'r') as f:
            content = f.read()
            policy_contents[file] = content
    except Exception as e:
        print(f"Error reading {file}: {e}")

# Display contents for analysis
for file, content in policy_contents.items():
    print(f"\n--- {file} ---")
    print(content[:500])  # Show first 500 chars
